import React, { useState } from "react";
import {
  FaCheck,
  FaEnvelope,
  FaHackerNews,
  FaLink,
  FaLinkedinIn,
  FaRedditAlien,
  FaShareAlt,
  FaWhatsapp,
} from "react-icons/fa";
import { FaXTwitter } from "react-icons/fa6";
import { shareTargets } from "./shareLinks";
import { getVisitorIntelligence } from "../../services/visitorIntelligence";
import "./share.css";

const ICONS = {
  linkedin: FaLinkedinIn,
  twitter: FaXTwitter,
  whatsapp: FaWhatsapp,
  reddit: FaRedditAlien,
  hackernews: FaHackerNews,
  email: FaEnvelope,
};

const canNativeShare = () =>
  typeof navigator !== "undefined" &&
  typeof navigator.share === "function" &&
  window.matchMedia?.("(pointer: coarse)").matches;

/**
 * Icon row of share targets. Every link is UTM-tagged (see shareLinks.js)
 * and every click is recorded as a "share" event for the dashboard.
 */
const ShareButtons = ({
  url,
  title,
  campaign,
  label = "Share",
  networks = ["linkedin", "twitter", "whatsapp", "reddit", "email"],
  onCopied,
  className = "",
}) => {
  const [copied, setCopied] = useState(false);
  const targets = shareTargets({ url, title, campaign });
  const track = (network) =>
    getVisitorIntelligence().trackEvent(
      "share",
      `${network}:${campaign || ""}`
    );

  const copy = async () => {
    try {
      await navigator.clipboard.writeText(targets.copy.url);
      setCopied(true);
      setTimeout(() => setCopied(false), 1800);
      onCopied?.();
    } catch {
      window.prompt("Copy this link", targets.copy.url);
    }
    track("copy_link");
  };

  const nativeShare = async () => {
    try {
      await navigator.share({ title, url: targets.native.url });
      track("native_share");
    } catch {
      /* dismissed */
    }
  };

  return (
    <div className={`sx-share ${className}`} role="group" aria-label={label}>
      {label && <span className="sx-share-label">{label}</span>}
      {canNativeShare() && (
        <button
          type="button"
          className="sx-share-btn"
          onClick={nativeShare}
          title="Share…"
        >
          <FaShareAlt aria-hidden="true" />
          <span className="sx-sr">Share…</span>
        </button>
      )}
      {networks.map((key) => {
        const Icon = ICONS[key];
        const target = targets[key];
        if (!Icon || !target) return null;
        return (
          <a
            key={key}
            className={`sx-share-btn sx-${key}`}
            href={target.href}
            target="_blank"
            rel="noopener noreferrer"
            title={`Share on ${target.label}`}
            // Recorded as a share, not an outbound click
            data-no-outbound
            onClick={() => track(key)}
          >
            <Icon aria-hidden="true" />
            <span className="sx-sr">Share on {target.label}</span>
          </a>
        );
      })}
      <button
        type="button"
        className={`sx-share-btn ${copied ? "is-done" : ""}`}
        onClick={copy}
        title={copied ? "Copied!" : "Copy link"}
      >
        {copied ? (
          <FaCheck aria-hidden="true" />
        ) : (
          <FaLink aria-hidden="true" />
        )}
        <span className="sx-sr">{copied ? "Copied" : "Copy link"}</span>
      </button>
    </div>
  );
};

export default ShareButtons;
