import React, { useEffect, useMemo, useRef } from "react";
import "./BlogHeroExtras.css";

/* ==========================================================
   BLOG HERO — COVER CONSTELLATION
   Recent post covers drift either side of the (compact, centred) hero,
   leaning with the cursor; hover shows the title, click opens the post.
   ========================================================== */

const reduceMotion = () =>
  typeof window !== "undefined" &&
  window.matchMedia &&
  window.matchMedia("(prefers-reduced-motion: reduce)").matches;

// Slots either side of the centred hero, as % of the stage: [left, top,
// width px, tilt deg, depth]. Left column then right column, so the first
// (newest) covers land nearest the headline.
const SLOTS = [
  [8, 10, 128, -4, 0.8],
  [83, 14, 128, 4, 0.8],
  [3, 56, 108, 3, 0.5],
  [88, 60, 108, -3, 0.5],
];

/* ---------------- Cover constellation ---------------- */
export function CoverConstellation({ blogs, openBlog }) {
  const stageRef = useRef(null);
  const covers = useMemo(
    () => blogs.filter((b) => b.coverImageURL).slice(0, SLOTS.length),
    [blogs]
  );

  // Lean with the cursor (CSS vars; depth per tile scales the shift)
  useEffect(() => {
    const el = stageRef.current;
    if (!el || reduceMotion()) return undefined;
    let raf = 0;
    let tx = 0;
    let ty = 0;
    let x = 0;
    let y = 0;
    const loop = () => {
      x += (tx - x) * 0.08;
      y += (ty - y) * 0.08;
      el.style.setProperty("--mx", x.toFixed(3));
      el.style.setProperty("--my", y.toFixed(3));
      raf =
        Math.abs(tx - x) + Math.abs(ty - y) > 0.001
          ? requestAnimationFrame(loop)
          : 0;
    };
    const onMove = (e) => {
      tx = (e.clientX / window.innerWidth) * 2 - 1;
      ty = (e.clientY / window.innerHeight) * 2 - 1;
      if (!raf) raf = requestAnimationFrame(loop);
    };
    window.addEventListener("pointermove", onMove, { passive: true });
    return () => {
      window.removeEventListener("pointermove", onMove);
      cancelAnimationFrame(raf);
    };
  }, []);

  if (!covers.length) return null;
  return (
    <div
      className="bh-stage bh-constellation"
      ref={stageRef}
      aria-label="Recent posts"
    >
      {covers.map((b, i) => {
        const [left, top, w, tilt, depth] = SLOTS[i];
        return (
          <button
            key={b.id}
            type="button"
            className="bh-tile"
            style={{
              left: `${left}%`,
              top: `${top}%`,
              width: w,
              "--tilt": `${tilt}deg`,
              "--depth": depth,
              "--delay": `${-i * 1.7}s`,
              "--dur": `${7 + (i % 3) * 1.6}s`,
            }}
            onClick={() => openBlog(b)}
            aria-label={`Open: ${b.title}`}
          >
            <img src={b.coverImageURL} alt="" loading="lazy" />
            <span className="bh-tile-title">{b.title}</span>
          </button>
        );
      })}
    </div>
  );
}
