import React, { useEffect, useMemo, useRef, useState } from "react";
import "./BlogLandingExtras.css";

/* ==========================================================
   BLOG LANDING EXTRAS
   - Continue reading: how far a visitor got in each post, kept in their
     own browser (localStorage, no sign-in, nothing sent anywhere)
   - Start here: three posts to read first — pinned from admin, else the
     highest-scored
   - Quick search: "/" or ⌘K / Ctrl+K opens a keyboard-driven search over
     titles, summaries, tags and topics
   ========================================================== */

/* ---------------- reading progress (per browser) ---------------- */
const PROGRESS_KEY = "blog:progress:v1";

export const loadProgress = () => {
  try {
    return JSON.parse(window.localStorage.getItem(PROGRESS_KEY)) || {};
  } catch (e) {
    return {};
  }
};

export const saveProgress = (id, p) => {
  try {
    const all = loadProgress();
    // finished posts drop out of "continue reading" but keep their mark
    all[id] = { p: p >= 0.97 ? 1 : Math.round(p * 100) / 100, t: Date.now() };
    window.localStorage.setItem(PROGRESS_KEY, JSON.stringify(all));
  } catch (e) {
    // storage blocked (private mode): resuming just won't be offered
  }
};

/* ---------------- Continue reading ---------------- */
// Posts started but not finished, most recently read first
export function ContinueReading({ posts, progress, onOpen }) {
  const items = useMemo(() => {
    const byId = Object.fromEntries(posts.map((b) => [b.id, b]));
    return Object.entries(progress)
      .filter(([id, v]) => byId[id] && v.p > 0.04 && v.p < 1)
      .sort((a, b) => b[1].t - a[1].t)
      .slice(0, 3)
      .map(([id, v]) => ({ blog: byId[id], p: v.p }));
  }, [posts, progress]);

  if (!items.length) return null;
  return (
    <div className="ble-continue" aria-label="Continue reading">
      <span className="ble-continue-label">Pick up where you left off</span>
      {items.map(({ blog, p }) => (
        <button
          key={blog.id}
          type="button"
          className="ble-chip"
          onClick={() => onOpen(blog, p)}
        >
          <span className="ble-chip-title">{blog.title}</span>
          <span className="ble-chip-meter" aria-hidden="true">
            <i style={{ width: `${Math.round(p * 100)}%` }} />
          </span>
          <span className="ble-chip-pct">{Math.round(p * 100)}%</span>
        </button>
      ))}
    </div>
  );
}

/* ---------------- Start here ---------------- */
// Pinned posts first (oldest pin first, so the order you pinned them holds),
// then the highest quality score, then newest. Skips the featured post.
export const pickStartHere = (posts, excludeId) => {
  const pool = posts.filter((b) => b.id !== excludeId);
  const ms = (ts) =>
    ts ? (ts.toMillis ? ts.toMillis() : new Date(ts).getTime()) : 0;
  const pinned = pool
    .filter((b) => b.pinned)
    .sort((a, b) => ms(a.pinnedAt) - ms(b.pinnedAt));
  const rest = pool
    .filter((b) => !b.pinned)
    .sort(
      (a, b) =>
        (b.qualityScore || 0) - (a.qualityScore || 0) ||
        ms(b.createdAt) - ms(a.createdAt)
    );
  return [...pinned, ...rest].slice(0, 3);
};

export function StartHere({
  posts,
  onOpen,
  getCategoryInfo,
  getReadTime,
  progress,
}) {
  if (!posts.length) return null;
  return (
    <section className="ble-start" aria-label="Start here">
      <div className="ble-start-head">
        <span className="ble-start-kicker">Start here</span>
        <span className="ble-start-sub">three to read first</span>
      </div>
      <div className="ble-start-row">
        {posts.map((b, i) => {
          const cat = getCategoryInfo(b.category);
          const done = progress[b.id] && progress[b.id].p >= 1;
          return (
            <button
              key={b.id}
              type="button"
              className="ble-start-item"
              style={{ "--cat": cat.color }}
              onClick={() => onOpen(b)}
            >
              <span className="ble-start-num">
                {String(i + 1).padStart(2, "0")}
              </span>
              {b.coverImageURL ? (
                <img
                  src={b.coverImageURL}
                  alt=""
                  loading="lazy"
                  className="ble-start-thumb"
                />
              ) : (
                <span
                  className="ble-start-thumb ble-start-thumb-blank"
                  aria-hidden="true"
                >
                  {b.icon || cat.icon}
                </span>
              )}
              <span className="ble-start-text">
                <span className="ble-start-title">{b.title}</span>
                <span className="ble-start-meta">
                  {cat.label} · {b.readTime || getReadTime(b.content)}
                  {done && <em> · read ✓</em>}
                </span>
              </span>
            </button>
          );
        })}
      </div>
    </section>
  );
}

/* ---------------- Quick search ---------------- */
const isTyping = (el) =>
  el &&
  (el.tagName === "INPUT" ||
    el.tagName === "TEXTAREA" ||
    el.tagName === "SELECT" ||
    el.isContentEditable);

// "/" (when not already typing) or ⌘K / Ctrl+K opens the search
export function useQuickSearchHotkey(setOpen, enabled = true) {
  useEffect(() => {
    if (!enabled) return undefined;
    const onKey = (e) => {
      const combo = (e.metaKey || e.ctrlKey) && e.key.toLowerCase() === "k";
      const slash =
        e.key === "/" &&
        !e.metaKey &&
        !e.ctrlKey &&
        !e.altKey &&
        !isTyping(document.activeElement);
      if (combo || slash) {
        e.preventDefault();
        setOpen(true);
      }
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [setOpen, enabled]);
}

export function QuickSearch({
  open,
  onClose,
  posts,
  onOpen,
  getCategoryInfo,
  getReadTime,
}) {
  const [q, setQ] = useState("");
  const [active, setActive] = useState(0);
  const inputRef = useRef(null);
  const listRef = useRef(null);

  useEffect(() => {
    if (!open) return;
    setQ("");
    setActive(0);
    const t = window.setTimeout(
      () => inputRef.current && inputRef.current.focus(),
      10
    );
    return () => window.clearTimeout(t);
  }, [open]);

  const results = useMemo(() => {
    const terms = q.toLowerCase().split(/\s+/).filter(Boolean);
    const scored = posts.map((b) => {
      const cat = getCategoryInfo(b.category);
      const title = (b.title || "").toLowerCase();
      const hay = [b.excerpt, (b.tags || []).join(" "), cat.label]
        .join(" ")
        .toLowerCase();
      let score = 0;
      for (const t of terms) {
        if (title.includes(t)) score += title.startsWith(t) ? 6 : 4;
        else if (hay.includes(t)) score += 1;
        else return null; // every term has to match somewhere
      }
      return { b, cat, score };
    });
    return scored
      .filter(Boolean)
      .sort((a, b) => b.score - a.score)
      .slice(0, 8);
  }, [q, posts, getCategoryInfo]);

  useEffect(() => setActive(0), [q]);

  // keep the highlighted row in view
  useEffect(() => {
    const el = listRef.current && listRef.current.children[active];
    if (el && el.scrollIntoView) el.scrollIntoView({ block: "nearest" });
  }, [active]);

  if (!open) return null;

  const choose = (r) => {
    if (!r) return;
    onClose();
    onOpen(r.b);
  };
  const onKeyDown = (e) => {
    if (e.key === "Escape") {
      e.preventDefault();
      onClose();
    } else if (e.key === "ArrowDown") {
      e.preventDefault();
      setActive((a) => Math.min(a + 1, results.length - 1));
    } else if (e.key === "ArrowUp") {
      e.preventDefault();
      setActive((a) => Math.max(a - 1, 0));
    } else if (e.key === "Enter") {
      e.preventDefault();
      choose(results[active]);
    }
  };

  return (
    // eslint-disable-next-line jsx-a11y/click-events-have-key-events, jsx-a11y/no-static-element-interactions
    <div className="ble-qs-backdrop" onClick={onClose}>
      <div
        className="ble-qs"
        role="dialog"
        aria-modal="true"
        aria-label="Search the blog"
        onClick={(e) => e.stopPropagation()}
        onKeyDown={onKeyDown}
      >
        <div className="ble-qs-bar">
          <svg viewBox="0 0 24 24" aria-hidden="true">
            <circle cx="11" cy="11" r="7" />
            <path d="m20 20-3.5-3.5" />
          </svg>
          <input
            ref={inputRef}
            value={q}
            onChange={(e) => setQ(e.target.value)}
            placeholder="Search posts by title, topic or tag…"
            aria-label="Search posts"
            aria-controls="ble-qs-list"
            aria-activedescendant={
              results[active] ? `ble-qs-${results[active].b.id}` : undefined
            }
          />
          <kbd>esc</kbd>
        </div>
        {results.length ? (
          <ul
            className="ble-qs-list"
            id="ble-qs-list"
            role="listbox"
            ref={listRef}
          >
            {results.map((r, i) => (
              <li
                key={r.b.id}
                id={`ble-qs-${r.b.id}`}
                role="option"
                aria-selected={i === active}
                className={i === active ? "is-active" : ""}
                style={{ "--cat": r.cat.color }}
                onMouseEnter={() => setActive(i)}
                onClick={() => choose(r)}
              >
                <span className="ble-qs-dot" aria-hidden="true" />
                <span className="ble-qs-text">
                  <b>{r.b.title}</b>
                  <span>{r.b.excerpt}</span>
                </span>
                <span className="ble-qs-meta">
                  {r.cat.label}
                  <br />
                  {r.b.readTime || getReadTime(r.b.content)}
                </span>
              </li>
            ))}
          </ul>
        ) : (
          <p className="ble-qs-empty">No posts match “{q}”.</p>
        )}
        <div className="ble-qs-foot">
          <span>
            <kbd>↑</kbd>
            <kbd>↓</kbd> to move
          </span>
          <span>
            <kbd>↵</kbd> to open
          </span>
          <span>
            <kbd>/</kbd> or <kbd>⌘K</kbd> anytime
          </span>
        </div>
      </div>
    </div>
  );
}
